import type { Bilingual } from './sentence-breakdowns'

export interface ReadingSentence { jp: string; translation: Bilingual; grammarIds: string[] }
export type ReadingParagraph = ReadingSentence[]
export function s(jp: string, en: string, vi: string, ...grammar: number[]): ReadingSentence {
  return { jp, translation: { en, vi }, grammarIds: grammar.map(n => `g_${String(n).padStart(3, '0')}`) }
}

